const Menu = ({ categories, addToCart }) => {
  const [selectedItem, setSelectedItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [activeCategory, setActiveCategory] = useState("Tout");
  const allDishes = categories.flatMap(c => (c.dishes || []).map(dish => ({ ...dish, categoryName: c.name })));
  const filteredDishes = allDishes.filter(item => (activeCategory === "Tout" || item.categoryName === activeCategory) && item.name.toLowerCase().includes(searchTerm.toLowerCase()));
  return (
    <PageLayout title="Menu">
      <div className="max-w-md mx-auto mb-8"><input type="text" placeholder="RECHERCHER..." className="w-full bg-white/5 border border-white/10 rounded-full py-5 px-10 text-white text-center font-black uppercase text-xs" onChange={(e) => setSearchTerm(e.target.value)} /></div>
      <div className="flex flex-wrap justify-center gap-3 mb-16">
        <button onClick={() => setActiveCategory("Tout")} className={`px-8 py-3 rounded-full font-black uppercase text-[10px] ${activeCategory === "Tout" ? "bg-orange-600 text-white shadow-lg" : "text-white/50 border border-white/10"}`}>Tout</button>
        {categories.map(cat => <button key={cat.id} onClick={() => setActiveCategory(cat.name)} className={`px-8 py-3 rounded-full font-black uppercase text-[10px] ${activeCategory === cat.name ? "bg-orange-600 text-white shadow-lg" : "text-white/50 border border-white/10"}`}>{cat.name}</button>)}
      </div>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {filteredDishes.map(item => (
          <div key={item.id} className="bg-black/40 border border-white/10 rounded-[3rem] p-8 text-center group">
            <div className="h-64 overflow-hidden rounded-2xl mb-6"><img src={item.image || "https://via.placeholder.com/300"} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition duration-500" /></div>
            <h3 className="text-2xl font-black text-white italic mb-2 uppercase">{item.name}</h3>
            <p className="text-orange-500 font-black text-2xl mb-6">{item.price} DH</p>
            <button onClick={() => setSelectedItem(item)} className="w-full py-4 bg-white rounded-2xl font-black uppercase text-[10px] hover:bg-orange-600 hover:text-white transition">Commander</button>
          </div>
        ))}
      </div>
      {selectedItem && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-md">
          <div className="bg-white rounded-[3rem] p-10 max-w-sm w-full text-center">
            <h3 className="text-2xl font-black mb-6 italic uppercase">Choisir le Mode</h3>
            <button onClick={() => { addToCart({...selectedItem, type: 'Sur Place'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-100 rounded-2xl font-black uppercase mb-4 hover:bg-orange-600 hover:text-white transition">🍽️ Sur Place</button>
            <button onClick={() => { addToCart({...selectedItem, type: 'À Emporter'}); setSelectedItem(null); }} className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase hover:bg-orange-600 transition">🛍️ À Emporter</button>
            <button onClick={() => setSelectedItem(null)} className="mt-6 text-gray-400 font-bold text-[10px] uppercase hover:text-red-500 transition">Annuler</button>
          </div>
        </div>
      )}
    </PageLayout>
  );
};

const Panier = ({ cart }) => (
  <PageLayout title="Panier">
    <div className="max-w-2xl mx-auto bg-white/10 backdrop-blur-2xl border border-white/20 p-12 rounded-[3.5rem] text-white font-bold italic">
